import{_ as a,H as i,f as t,i as s}from"./chunks/framework.BH2BK_3i.js";const B=JSON.parse('{"title":"39 | Elasticsearch高可用：怎么保证Elasticsearch的高可用？","description":"","frontmatter":{},"headers":[{"level":2,"title":"Elasticsearch 节点角色","slug":"elasticsearch-节点角色","link":"#elasticsearch-节点角色","children":[]},{"level":2,"title":"写入数据","slug":"写入数据","link":"#写入数据","children":[{"level":3,"title":"Translog","slug":"translog","link":"#translog","children":[]}]},{"level":2,"title":"Elasticsearch 索引与分片","slug":"elasticsearch-索引与分片","link":"#elasticsearch-索引与分片","children":[]},{"level":2,"title":"面试准备","slug":"面试准备","link":"#面试准备","children":[]},{"level":2,"title":"基本思路","slug":"基本思路","link":"#基本思路","children":[]},{"level":2,"title":"Elasticsearch 高可用方案","slug":"elasticsearch-高可用方案","link":"#elasticsearch-高可用方案","children":[{"level":3,"title":"限流保护节点","slug":"限流保护节点","link":"#限流保护节点","children":[]},{"level":3,"title":"利用消息队列削峰","slug":"利用消息队列削峰","link":"#利用消息队列削峰","children":[]},{"level":3,"title":"保护协调节点","slug":"保护协调节点","link":"#保护协调节点","children":[]},{"level":3,"title":"双集群","slug":"双集群","link":"#双集群","children":[]}]},{"level":2,"title":"面试思路总结","slug":"面试思路总结","link":"#面试思路总结","children":[]},{"level":2,"title":"思考题","slug":"思考题","link":"#思考题","children":[]}],"relativePath":"后端工程师的高阶面经/39｜Elasticsearch高可用：怎么保证Elasticsearch的高可用？.md","filePath":"后端工程师的高阶面经/39｜Elasticsearch高可用：怎么保证Elasticsearch的高可用？.md","lastUpdated":1795554391000}'),l={name:"后端工程师的高阶面经/39｜Elasticsearch高可用：怎么保证Elasticsearch的高可用？.md"};function E(c,e,r,h,n,p){return i(),t("div",null,[...e[0]||(e[0]=[s('<h1 id="_39-elasticsearch高可用-怎么保证elasticsearch的高可用" tabindex="-1">39 | Elasticsearch高可用：怎么保证Elasticsearch的高可用？ <a class="header-anchor" href="#_39-elasticsearch高可用-怎么保证elasticsearch的高可用" aria-label="Permalink to &quot;39 | Elasticsearch高可用：怎么保证Elasticsearch的高可用？&quot;">​</a></h1><p>你好，我是大明。今天开始我们要学习一个新的主题——NoSQL。在这个主题里面，我们先从 Elasticsearch 开始学起。</p><p>Elasticsearch 从面试的热度上来说，肯定是比不过数据库、缓存和消息队列。但是Elasticsearch 在中大型公司里面又非常常用，这意味着如果你希望跳槽到一些比较大型的公司，那么 Elasticsearch 还是有比较大的概率考到的。</p><p>就像我之前说的，目前互联网行业面试中间件的话，就是高可用和高性能。而具体到每一个点，又可以拆成两个方向。</p><ol><li><p>中间件是如何做到高可用 / 高性能的？</p></li><li><p>你在实践中怎么做到高可用 / 高性能？</p></li></ol><p>那么这一节课我们就先来看高可用这一个点，并给出几个有亮点的提高可用性的方案，让你在面试的时候赢得竞争优势。在这里我就不严格区分 Elasticsearch 还是 Lucene，统一使用Elasticsearch。我们先来看看 Elasticsearch 中的节点角色。</p><h2 id="elasticsearch-节点角色" tabindex="-1">Elasticsearch 节点角色 <a class="header-anchor" href="#elasticsearch-节点角色" aria-label="Permalink to &quot;Elasticsearch 节点角色&quot;">​</a></h2><p>Elasticsearch 的节点可以分成很多种角色，并且一个节点可以扮演多种角色。这里我列举几种主要的。</p><ul><li><p>候选主节点（Master-eligible Node)：可以被选举为主节点的节点。主节点主要负责集群本身的管理，比如说创建索引。类似的还有仅投票节点（Voting-only Node），这类节点只参与主从选举，但是自身并不会被选举为主节点。</p></li><li><p>协调节点（Coordinating Node）：协调节点负责协调请求的处理过程。一个查询请求会被发送到协调节点上，协调节点确定数据节点，然后让数据节点执行查询，最后协调节点合并数据节点返回的结果集。大多数节点都会兼任这个角色。</p></li><li><p>数据节点（Data Node）：存储数据的节点。当协调节点发来查询请求的时候，也会执行查询并且把结果返回给协调节点。类似的还有热数据节点（Hot Data Node）、暖数据节点（Warm Data Node）、冷数据节点（Cold Data Node），你从名字就可以看出来，它们只是用于存储不同热度的数据。</p></li></ul><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%90%8E%E7%AB%AF%E5%B7%A5%E7%A8%8B%E5%B8%88%E7%9A%84%E9%AB%98%E9%98%B6%E9%9D%A2%E7%BB%8F/images/39/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%90%8E%E7%AB%AF%E5%B7%A5%E7%A8%8B%E5%B8%88%E7%9A%84%E9%AB%98%E9%98%B6%E9%9D%A2%E7%BB%8F/images/39/1.png" alt=""></a></p><p>给节点设置不同的角色的原则就一条：有钱就专款专用，没钱就兼任。兼任就是指你一个节点扮演了多个角色。意思是，如果有钱有足够的资源，那么你就不要让节点兼任。如果没钱，那么就可以考虑兼任。但是不管怎样，兼任都有可能引起性能问题。</p><p>因此，如果真的追求高性能高可用，就还是让节点只扮演一个角色比较好。</p><h2 id="写入数据" tabindex="-1">写入数据 <a class="header-anchor" href="#写入数据" aria-label="Permalink to &quot;写入数据&quot;">​</a></h2><p>在 Elasticsearch 中，写入数据整体上是这样的：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%90%8E%E7%AB%AF%E5%B7%A5%E7%A8%8B%E5%B8%88%E7%9A%84%E9%AB%98%E9%98%B6%E9%9D%A2%E7%BB%8F/images/39/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%90%8E%E7%AB%AF%E5%B7%A5%E7%A8%8B%E5%B8%88%E7%9A%84%E9%AB%98%E9%98%B6%E9%9D%A2%E7%BB%8F/images/39/2.png" alt=""></a></p><p>我们来简单描述一下这个过程。</p><ol><li><p>文档首先被写入到 Buffer 里面，这个是 Elasticsearch 自己的 Buffer。</p></li><li><p>定时刷新到 Page Cache 里面。这个过程叫做 refresh，默认是 1 秒钟执行一次。</p></li><li><p>刷新到磁盘中，这时候还会同步记录一个 Commit Point。</p></li></ol><p>你在图里面还可以注意到，在写入到 Page Cache 之后会产生很多段（Segment），一个段里面包含了多个文档。文档只有写到了这里之后才可以被搜索到，因此从支持搜索的角度来说，Elasticsearch 是近实时的。</p><p>不断写入会不断产生段，而每一个段都要消耗 CPU、内存和文件句柄，所以需要考虑合并。但是你也注意到了，这些段本身还在支持搜索，因此在合并段的时候，不能对已有的查询产生影响。</p><p>看到这里你应该觉得很熟悉，因为在数据迁移里面你也面临着同样的困难。所以，即便不看源码你都能猜到基本的过程。</p><ol><li><p>已有的段不动。</p></li><li><p>创建一个新的段，把已有段的数据写过去，标记为删除的文档就不会写到段里面。</p></li><li><p>告知查询使用新的段。</p></li><li><p>等使用老的段的查询都结束了，直接删掉老的段。</p></li></ol><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%90%8E%E7%AB%AF%E5%B7%A5%E7%A8%8B%E5%B8%88%E7%9A%84%E9%AB%98%E9%98%B6%E9%9D%A2%E7%BB%8F/images/39/3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%90%8E%E7%AB%AF%E5%B7%A5%E7%A8%8B%E5%B8%88%E7%9A%84%E9%AB%98%E9%98%B6%E9%9D%A2%E7%BB%8F/images/39/3.png" alt=""></a></p><p>那么查询怎么知道应该使用合并段了呢？这都依赖于一个统一的机制，就是 Commit Point。你可以理解成，它里面记录了哪些段是可用的。所以当合并段之后，产生一个新的 CommitPoint，里面有合并后的段，但是没有被合并的段，就相当于告知了查询使用新的段。</p><h3 id="translog" tabindex="-1">Translog <a class="header-anchor" href="#translog" aria-label="Permalink to &quot;Translog&quot;">​</a></h3><p>实际上，Elasticsearch 在写入的时候，还要写入一个东西，也就是 Translog。直观来说，你可以把这个看成是 MySQL 里和 redo log 差不多的东西。也就是如果宕机了，Elasticsearch可以用 Translog 来恢复数据。</p><p>你可以对比一下 MySQL 的写入过程和 Elasticsearch 的写入过程。</p><ul><li><p>MySQL 写入的时候，其实只是修改了内存里的值，然后记录了日志，也就是 binlog、redolog 和 undo log。</p></li><li><p>Elasticsearch 写入的时候，也是写到了 Buffer 里，然后记录了 Translog。</p></li></ul><p>不同的是，Translog 是固定间隔刷新到磁盘上的，默认情况下是 5 秒。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%90%8E%E7%AB%AF%E5%B7%A5%E7%A8%8B%E5%B8%88%E7%9A%84%E9%AB%98%E9%98%B6%E9%9D%A2%E7%BB%8F/images/39/4.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%90%8E%E7%AB%AF%E5%B7%A5%E7%A8%8B%E5%B8%88%E7%9A%84%E9%AB%98%E9%98%B6%E9%9D%A2%E7%BB%8F/images/39/4.png" alt=""></a></p><p>类似于在 MySQL 里讨论的，Translog 是只追加的，也就是顺序写的，所以效率非常高。它只有在刷新到磁盘上的时候，才会非常慢。</p><p>这时候你就会注意到，就算有 Translog，还是有数据丢失的可能。最差的情况下，会丢失 5s的数据。</p><h2 id="elasticsearch-索引与分片" tabindex="-1">Elasticsearch 索引与分片 <a class="header-anchor" href="#elasticsearch-索引与分片" aria-label="Permalink to &quot;Elasticsearch 索引与分片&quot;">​</a></h2><p>在一般的语境下，一个 Elasticsearch 的索引并不仅仅指倒排索引，还包括了对应的文档。这个和关系型数据库下的语义是不同的。</p><p>Elasticsearch 的一个索引有多个分片，每个分片又有主从结构。这种结构相信你已经很熟悉了，它类似于分库分表。作为类比，你可以这样理解。</p><ul><li><p>一个索引就是一个逻辑表。</p></li><li><p>分片就是分库分表。</p></li><li><p>每个分片都有主从结构，在分库分表里面，一般也是用主从集群来存储数据。</p></li></ul><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%90%8E%E7%AB%AF%E5%B7%A5%E7%A8%8B%E5%B8%88%E7%9A%84%E9%AB%98%E9%98%B6%E9%9D%A2%E7%BB%8F/images/39/5.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%90%8E%E7%AB%AF%E5%B7%A5%E7%A8%8B%E5%B8%88%E7%9A%84%E9%AB%98%E9%98%B6%E9%9D%A2%E7%BB%8F/images/39/5.png" alt=""></a></p><p>Elasticsearch 会尽量把分片分散在不同的节点上，这一点和 Kafka 尽量把分区分散在不同的broker 上是一样的，都是为了保证在节点崩溃的时候将影响最小化。</p><p>那么主分片崩溃之后，是怎么选出新的主分片呢？答案是主节点选择一个分片作为主分片。这有点类似于 Redis Sentinel 里面的机制，如果主节点宕机了，那么 Sentinel 会从从节点里面挑出来一个作为主节点。</p><h2 id="面试准备" tabindex="-1">面试准备 <a class="header-anchor" href="#面试准备" aria-label="Permalink to &quot;面试准备&quot;">​</a></h2><p>你在面试前，应该在公司内部收集好这些信息。</p><ul><li><p>你们公司有没有使用 Elasitcsearch？用来解决什么问题？</p></li><li><p>你用的 Elasticsearch 的性能怎么样？读写流量多大？存储的数据量又有多大？</p></li><li><p>你创建的索引有多大？多少个分片？你是怎么确定分片数量的？</p></li><li><p>你们公司有没有使用一些措施来保证 Elasticsearch 的可用性？有没有用过 Elasticsearch的网关？</p></li><li><p>你们公司的 Elasticsearch 有没有出过问题？出了什么问题？最终又是怎么解决的？</p></li></ul><p>如果你在一个小公司，并且公司没有使用 Elasticsearch，那么你可以通过各种途径收集一些使用 Elasticsearch 的基本案例，这样在面试讲到一些理论的时候，你可以用这些案例来佐证。不过还是建议优先使用自己公司的例子。</p><p>因为这节课具体讨论的是提高 Elasticsearch 的可用性，所以你可以考虑把它纳入到你提高整个系统可用性方案中，做成其中的一环。你可以在项目介绍的时候强调一下你的项目可用性的一个关键点就是 Elasticsearch，从而打开话题。</p><p>和 Elasticsearch 相关的面试题目有很多，比如：</p><ul><li><p>你有没有用过 Elasticsearch？用来解决什么问题？</p></li><li><p>你用 Elasticseach 的过程中，有没有遇到什么问题？最终是如何解决的？</p></li><li><p>为什么说 Elasticsearch 是近实时的？</p></li><li><p>Elasticsearch 的 flush 是指什么？refresh 又是指什么？</p></li><li><p>Elasticsearch 的写入过程是怎样的？</p></li></ul><h2 id="基本思路" tabindex="-1">基本思路 <a class="header-anchor" href="#基本思路" aria-label="Permalink to &quot;基本思路&quot;">​</a></h2><p>如果你是业务开发，而且面试的不是什么架构师之类的岗位，那么 Elasticsearch 的面试会简单很多，基本上就是问一下 Elasticsearch 的基础知识。比较关键的一部分我已经在前置知识里面写了，还有一部分和倒排索引有关的内容，下节课我会仔细讲一讲。</p><p>Elasticsearch 最基本的可用性保障就是分片，而且是主从分片。所以在遇到 Elasticsearch 是如何做到高可用这个问题的时候，你要先提到这一点。</p><ul><li>Elasticsearch 高可用的核心是分片，并且每个分片都有主从之分。也就是说，万一主分片崩溃了，还可以使用从分片，从而保证了最基本的可用性。</li></ul><p>然后你要接着补充第二个 Translog 的作用。</p><ul><li>而且 Elasticsearch 在写入数据的过程中，为了保证高性能，都是写到自己的 Buffer 里面，后面再刷新到磁盘上。所以为了降低数据丢失的风险，Elasticsearch 还额外写了一个Translog，它就类似于 MySQL 里的 redo log。后面 Elasticsearch 崩溃之后，可以利用Translog 来恢复数据。</li></ul><p>如果面试官追问分片和写入过程，你就可以根据前置知识里面的内容来回答。</p><p>紧接着你可以尝试把话题引导到你准备的高可用方案中。</p><ul><li>我维护的业务对可用性的要求比较高，所以在 Elasticsearch 的基础上，我还做了一些额外的优化，来保证 Elasticsearch 的高可用。</li></ul><h2 id="elasticsearch-高可用方案" tabindex="-1">Elasticsearch 高可用方案 <a class="header-anchor" href="#elasticsearch-高可用方案" aria-label="Permalink to &quot;Elasticsearch 高可用方案&quot;">​</a></h2><p>这里我给出几个可行的实践方案，让你进一步刷出亮点。</p><h3 id="限流保护节点" tabindex="-1">限流保护节点 <a class="header-anchor" href="#限流保护节点" aria-label="Permalink to &quot;限流保护节点&quot;">​</a></h3><p>限流算是一个治标的策略，但是它能够保证你的 Elasticsearch 不会因为突发大流量而直接崩溃。</p><p>你可以通过 Elasticsearch 的插件机制来实现自定义的限流策略。注意 Elasticsearch 集群本身提供了限流的功能，并且你也可以通过控制线程池大小和队列大小来间接实现限流的功能。</p><p>因此如果你打算利用插件来提供限流功能的时候，就一定要有特殊之处。比如说你可以考虑结合 Elasticsearch 的内存使用率和 CPU 使用率设计一个限流策略。这个限流策略在微服务部分我也提到过了，你可以复习一下。</p><ul><li>之前我用 Elasticsearch 的插件机制，设计过一个限流插件。这个限流插件的功能还是很简单的，就是根据 Elasticsearch 当前的内存使用率和 CPU 使用率来判断是否需要执行限流。不管是内存使用率还是 CPU 使用率，只要超过阈值一段时间，就触发限流。</li></ul><p>这里面试官也会考察你怎么确定限流的阈值，超过阈值多久才会触发限流，限流之后怎么恢复等问题。</p><p>当然，如果你会研发限流插件，你也可以用插件来实现熔断、降级。熔断比较好处理，就是直接拒绝新的查询请求，但是降级这个就要考虑怎么降级了。如果你能够知道不同查询的业务价值，那么你就可以考虑触发降级的时候优先保障核心业务的请求，但是把非核心的请求拒绝了。</p><p>总而言之，你之前在微服务学习到的熔断、限流、降级的思想，在这里一样适用。</p><p>如果你从来没有研发过 Elasticsearch 插件，那么也可以考虑其他两种策略，一种是在Elasticsearch 之前加一个网关，查询经过网关的时候会被限流、熔断或者降级。当然，引代理也可以。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%90%8E%E7%AB%AF%E5%B7%A5%E7%A8%8B%E5%B8%88%E7%9A%84%E9%AB%98%E9%98%B6%E9%9D%A2%E7%BB%8F/images/39/6.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%90%8E%E7%AB%AF%E5%B7%A5%E7%A8%8B%E5%B8%88%E7%9A%84%E9%AB%98%E9%98%B6%E9%9D%A2%E7%BB%8F/images/39/6.png" alt=""></a></p><p>目前市面上的这方面的产品不多，比较成熟的就是极限网关。所以我建议你用一种自己了解但是没有实践过的话术来说。</p><ul><li>我还了解过 Elasticsearch 网关或者代理，希望能够借助这些产品来做 Elasticsearch 的治理。比如说借助网关来做熔断、限流、降级这种，但是市面上相关的产品比较少，也担心引入网关之后的性能损耗，所以最终并没有实施这个方案。</li></ul><p>另外一种是在客户端这边限流。也就是各个业务方需要限制住自己的查询频率，防止把整个Elasticsearch 打崩。相比之下，这种方式是最好落地的。</p><ul><li>我们这边为了保护 Elasticsearch，在客户端这边都是做了限流的。比如说某个业务的查询都比较慢，对 Elasticsearch 的压力很大，那么限流的阈值就比较小。</li></ul><p>不过 Elasticsearch 设计之初就是为了支持高并发大数据的，所以最佳方式还是要考虑扩容。</p><ul><li>不管如何，限流都只能算是治标。如果经常触发限流，或者发现 Elasticsearch 有性能问题，那么还是要及时扩容的。</li></ul><h3 id="利用消息队列削峰" tabindex="-1">利用消息队列削峰 <a class="header-anchor" href="#利用消息队列削峰" aria-label="Permalink to &quot;利用消息队列削峰&quot;">​</a></h3><p>在一些对数据实时性要求不高的场景下，完全可以考虑在业务方和 Elasticsearch 中间加入一个消息队列。</p><p>你可以抓住关键字削峰和限流来回答。</p><ul><li><p>之前我优化过我们业务的架构，就是在数据同步到 Elasticsearch 之前，加入一个消息队列来削峰。在早期的时候，我们都是双写，一方面写数据库，一方面写 Elasticsearch。那么在业务高峰期，Elasticsearch 就会有性能瓶颈。</p></li><li><p>而实际上，我们的业务对实时性的要求不高。在这种情况下，我引入了消息队列。业务方只是写入数据库就返回。然后我们监听 binlog，并且生成消息丢到 Kafka 上。在这种情况下，Elasticsearch 空闲的话，消费速率就高；如果 Elasticsearch 性能比较差，那么消费就比较慢。这样就起到了削峰和限流的效果。</p></li></ul><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%90%8E%E7%AB%AF%E5%B7%A5%E7%A8%8B%E5%B8%88%E7%9A%84%E9%AB%98%E9%98%B6%E9%9D%A2%E7%BB%8F/images/39/7.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%90%8E%E7%AB%AF%E5%B7%A5%E7%A8%8B%E5%B8%88%E7%9A%84%E9%AB%98%E9%98%B6%E9%9D%A2%E7%BB%8F/images/39/7.png" alt=""></a></p><p>在这个架构的基础上，还可以考虑引入降级，也就是在 Elasticsearch 真的有性能问题的时候，关闭一部分消费者。</p><ul><li><p>而在这个架构的基础上，我还做了一个简单的降级。也就是我有两类消费者写入数据到Elasticsearch。一类是核心数据消费者，一类是非核心数据消费者。</p></li><li><p>那么如果我在监控到 Elasticsearch 性能已经比较差了，比如说写入的时候会遇到超时问题，那么我就把非核心数据消费者停下来。等 Elasticsearch 恢复过来再启动。</p></li></ul><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%90%8E%E7%AB%AF%E5%B7%A5%E7%A8%8B%E5%B8%88%E7%9A%84%E9%AB%98%E9%98%B6%E9%9D%A2%E7%BB%8F/images/39/8.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%90%8E%E7%AB%AF%E5%B7%A5%E7%A8%8B%E5%B8%88%E7%9A%84%E9%AB%98%E9%98%B6%E9%9D%A2%E7%BB%8F/images/39/8.png" alt=""></a></p><p>甚至更加极端一点，如果是在大促或者秒杀这种活动中，你可以把整个数据同步都停掉，让Elasticsearch 只支持查询操作。如果你所在的业务是电商类的，那么你可以考虑使用这个策略。</p><h3 id="保护协调节点" tabindex="-1">保护协调节点 <a class="header-anchor" href="#保护协调节点" aria-label="Permalink to &quot;保护协调节点&quot;">​</a></h3><p>在 Elasticsearch 里，比较容易出现问题的还有协调节点。协调节点就类似于分库分表代理，它负责分发请求，然后处理结果集。</p><p>那么你可以预计到，如果一个查询需要消耗非常多的资源，就有可能把协调节点搞崩溃。举个简单的例子，假如说你有一个查询命中了十个分片，并且每个分片都返回了几万条数据，那么协调节点本身的资源使用量一下就会上去，甚至出现 CPU 100% 或者 OOM 等问题。</p><p>因此要保证 Elasticsearch 高可用就要考虑防止突发大请求打崩协调节点的问题。</p><p>整个面试思路是层层递进的。首先你可以指出如果公司内部资源比较多，那么可以考虑部署纯粹的协调节点。</p><ul><li>要想提高 Elasticsearch 的可用性，就要想办法防止协调节点在遇到大请求的时候崩溃。最简单的做法就是使用纯粹的协调节点。比如说专门部署一批节点，只扮演协调节点的角色。</li></ul><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%90%8E%E7%AB%AF%E5%B7%A5%E7%A8%8B%E5%B8%88%E7%9A%84%E9%AB%98%E9%98%B6%E9%9D%A2%E7%BB%8F/images/39/9.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%90%8E%E7%AB%AF%E5%B7%A5%E7%A8%8B%E5%B8%88%E7%9A%84%E9%AB%98%E9%98%B6%E9%9D%A2%E7%BB%8F/images/39/9.png" alt=""></a></p><p>这个思路总体上属于钞能力的范畴，所以你可以接着补充怎么用好这些协调节点，关键词就是隔离。</p><ul><li><p>如果整个 Elasticsearch 除了这种纯粹的协调节点，还有一些兼任多个角色的协调节点，那么就还可以考虑使用隔离策略。也就是说，如果客户端能够判定自己是大请求，就将请求发送到纯粹的协调节点上，否则发送到其他兼任的协调节点上。</p></li><li><p>这种做法的好处就是，大请求即便把协调节点打崩了，也只会影响到其他大请求。但是占据绝大多数的普通请求，并不会受到影响。</p></li></ul><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%90%8E%E7%AB%AF%E5%B7%A5%E7%A8%8B%E5%B8%88%E7%9A%84%E9%AB%98%E9%98%B6%E9%9D%A2%E7%BB%8F/images/39/10.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%90%8E%E7%AB%AF%E5%B7%A5%E7%A8%8B%E5%B8%88%E7%9A%84%E9%AB%98%E9%98%B6%E9%9D%A2%E7%BB%8F/images/39/10.png" alt=""></a></p><p>这种做法的好处是和隔离结合在了一起，因此你可以尝试把话题引导到隔离策略上。</p><p>在一些技术实力很强的大厂，它们还会对 Elasticsearch 进行二次开发。可以修改协调节点的逻辑，让协调节点在资源快不足的时候，直接拒绝这种大请求。如果你在大厂，可以了解一下自己公司有没有在这方面做优化。</p><p>你可以在这个基础上进一步总结，就是只使用单一角色的节点以提高可用性。</p><ul><li>在资源足够的情况下，我是建议所有的节点都只扮演单一角色。这样做不仅仅能够带来可用性的提升，也能带来性能的提升。</li></ul><h3 id="双集群" tabindex="-1">双集群 <a class="header-anchor" href="#双集群" aria-label="Permalink to &quot;双集群&quot;">​</a></h3><p>双集群算是一个很高级，投入也很大的高可用方案。</p><p>最简单的方案就是直接使用付费的 CCR 跨集群复制，这个基本上就不需要你操心。不过这个也属于钞能力，面试的时候简单提一下就可以。</p><ul><li>提高 Elasticsearch 可用性还有一个方法，就是使用双集群。比如说直接使用付费的 CCR功能，不过我司比较穷，肯定是不愿意买的。</li></ul><p>在不使用这种付费功能的情况下，就只能考虑自己做了。这里有一个比较简单的方案，假如说有 A 和 B 两个集群，那么基本思路就是这样的：</p><ul><li><p>使用消息队列来保持双写。</p></li><li><p>在查询的时候，优先使用 A 集群，当确认 A 集群出了问题的时候，切换到 B 集群。</p></li></ul><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%90%8E%E7%AB%AF%E5%B7%A5%E7%A8%8B%E5%B8%88%E7%9A%84%E9%AB%98%E9%98%B6%E9%9D%A2%E7%BB%8F/images/39/11.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%90%8E%E7%AB%AF%E5%B7%A5%E7%A8%8B%E5%B8%88%E7%9A%84%E9%AB%98%E9%98%B6%E9%9D%A2%E7%BB%8F/images/39/11.png" alt=""></a></p><p>你抓住关键词消息队列双写回答。</p><ul><li>我们采用的是一个比较简单的双集群方案。就是写入的时候并不是直接写入到Elasticsearch，而是写入到消息队列，而后启动两个消费者，分别消费消息，然后写到两个集群 AB 里面。关键在于查询的时候，要判断集群 A 有没有出问题，出了问题就切换到集群 B。</li></ul><p>而怎么判断集群 A 是否已经出问题，你一样可以参考微服务中判断节点是否健康的部分，思路都是类似的，这里我就不重复了。</p><p>具体怎么切换，有两种思路。一种是你使用的客户端切换，一种是利用 DNS 机制切换。也就是说，正常情况下，你使用的 Elasticsearch 的连接信息，DNS 解析的时候返回的是集群 A 的IP。但是当触发了容灾切换的时候，DNS 解析得到的是集群 B 的地址。</p><p>你在回答的时候可以选择其中任意一种，这里我以客户端为例来说一说。</p><ul><li>为了实现自动切换的效果，我们对 Elasticsearch 的客户端进行了二次封装。在封装之后，正常情况下，会访问集群 A。同时客户端监控集群 A 的响应时间。如果响应时间超出预期，又或者返回了比较多超时响应，客户端就会自动切换到集群 B 上。</li></ul><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%90%8E%E7%AB%AF%E5%B7%A5%E7%A8%8B%E5%B8%88%E7%9A%84%E9%AB%98%E9%98%B6%E9%9D%A2%E7%BB%8F/images/39/12.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%90%8E%E7%AB%AF%E5%B7%A5%E7%A8%8B%E5%B8%88%E7%9A%84%E9%AB%98%E9%98%B6%E9%9D%A2%E7%BB%8F/images/39/12.png" alt=""></a></p><h2 id="面试思路总结" tabindex="-1">面试思路总结 <a class="header-anchor" href="#面试思路总结" aria-label="Permalink to &quot;面试思路总结&quot;">​</a></h2><p>这一节课我们讨论的是 Elasticsearch 的高可用问题。首先我给你介绍了 Elasticsearch 中的节点角色、Elasticsearch 的写入过程，以及 Elasticsearch 索引与分片的关系。</p><p>然后我讲了四个提高 Elasticsearch 可用性的方案。</p><ul><li><p>限流保护节点：你可以考虑使用 Elasticsearch 的插件机制、网关或者在客户端限流。也不仅仅是限流，你也可以用来熔断或者降级。</p></li><li><p>利用消息队列削峰：这个案例你也可以用在消息队列的面试中。</p></li><li><p>保护协调节点：因为查询总是先到协调节点，而后协调节点再分发个数据节点执行。并且协调节点自己还要处理结果集，所以它也是可用性的瓶颈。最佳策略就是让部分节点只充当协调节点。在这个基础上可以考虑根据请求大小、业务价值来对协调节点进行分组与隔离</p></li><li><p>双集群：大部分时候，只有不差钱的公司才会考虑为了一点点的可用性提升而引入双集群，这里我介绍了钞能力 CCR 方案和使用消息队列完成双写的双集群方案。</p></li></ul><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%90%8E%E7%AB%AF%E5%B7%A5%E7%A8%8B%E5%B8%88%E7%9A%84%E9%AB%98%E9%98%B6%E9%9D%A2%E7%BB%8F/images/39/13.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%90%8E%E7%AB%AF%E5%B7%A5%E7%A8%8B%E5%B8%88%E7%9A%84%E9%AB%98%E9%98%B6%E9%9D%A2%E7%BB%8F/images/39/13.png" alt=""></a></p><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><p>最后请你来思考两个问题。</p><ul><li><p>这节课我提到了主分片是由主节点选出来的，那么主节点自己又是怎么选出来的呢？</p></li><li><p>你还听说过哪些能够进一步提高 Elasticsearch 可用性的方案？可以分享到评论区，如果你觉得这节课对你有帮助的话，也欢迎你分享给其他朋友，我们下节课再见！</p></li></ul>',117)])])}const A=a(l,[["render",E]]);export{B as __pageData,A as default};
